from collections import deque

class Solution:
    def minimumObstacles(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dist = [[float("inf")] * n for _ in range(m)]
        dist[0][0] = 0
        q = deque([(0, 0, 0)])
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while q:
            d, r, c = q.popleft()
            if r == m - 1 and c == n - 1:
                return d
            if d > dist[r][c]:
                continue
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    w = grid[nr][nc]
                    if dist[r][c] + w < dist[nr][nc]:
                        dist[nr][nc] = dist[r][c] + w
                        if w == 0:
                            q.appendleft((dist[nr][nc], nr, nc))
                        else:
                            q.append((dist[nr][nc], nr, nc))
        return dist[m - 1][n - 1]

class Solution {
public:
    int minimumObstacles(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<int>> dist(m, std::vector<int>(n, 1e9));
        dist[0][0] = 0;
        std::deque<std::pair<int, int>> dq;
        dq.push_back({0, 0});
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!dq.empty()) {
            auto [r, c] = dq.front(); dq.pop_front();
            if (r == m - 1 && c == n - 1) return dist[r][c];
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int w = grid[nr][nc];
                    if (dist[r][c] + w < dist[nr][nc]) {
                        dist[nr][nc] = dist[r][c] + w;
                        if (w == 0) dq.push_front({nr, nc});
                        else dq.push_back({nr, nc});
                    }
                }
            }
        }
        return dist[m - 1][n - 1];
    }
};

class Solution {
    public int minimumObstacles(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] dist = new int[m][n];
        for (int[] row : dist) java.util.Arrays.fill(row, (int) 1e9);
        dist[0][0] = 0;
        java.util.Deque<int[]> dq = new java.util.ArrayDeque<>();
        dq.offer(new int[]{0, 0});
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!dq.isEmpty()) {
            int[] cell = dq.pollFirst();
            int r = cell[0], c = cell[1];
            if (r == m - 1 && c == n - 1) return dist[r][c];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int w = grid[nr][nc];
                    if (dist[r][c] + w < dist[nr][nc]) {
                        dist[nr][nc] = dist[r][c] + w;
                        if (w == 0) dq.offerFirst(new int[]{nr, nc});
                        else dq.offerLast(new int[]{nr, nc});
                    }
                }
            }
        }
        return dist[m - 1][n - 1];
    }
}

var minimumObstacles = function(grid) {
    const m = grid.length, n = grid[0].length;
    const dist = Array.from({ length: m }, () => new Int32Array(n).fill(1e9));
    dist[0][0] = 0;
    const dq = [[0, 0]];
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (dq.length > 0) {
        const [r, c] = dq.shift();
        if (r === m - 1 && c === n - 1) return dist[r][c];
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                const w = grid[nr][nc];
                if (dist[r][c] + w < dist[nr][nc]) {
                    dist[nr][nc] = dist[r][c] + w;
                    if (w === 0) dq.unshift([nr, nc]);
                    else dq.push([nr, nc]);
                }
            }
        }
    }
    return dist[m - 1][n - 1];
};
